const d = $input.first().json;

// Convertir ruta local a URL pública
// La ruta en DB es tipo: mockups/ARCHIVO.jpg o ruta completa Windows
let rutaRaw = d.ruta || d.archivo || '';
let imageUrl = '';

if (rutaRaw.startsWith('http')) {
  imageUrl = rutaRaw;
} else {
  // Limpiar ruta Windows y convertir a URL
  rutaRaw = rutaRaw.replace(/\\/g, '/');
  // Quitar partes de ruta local hasta encontrar 'mockups' o 'imagenes'
  const partesMockups = rutaRaw.split('mockups/');
  const partesImagenes = rutaRaw.split('imagenes/');

  if (partesMockups.length > 1) {
    imageUrl = 'https://noxertez.com/mockups/' + partesMockups[partesMockups.length - 1];
  } else if (partesImagenes.length > 1) {
    imageUrl = 'https://noxertez.com/imagenes/' + partesImagenes[partesImagenes.length - 1];
  } else {
    // Último recurso: usar el nombre de archivo directamente
    const archivo = rutaRaw.split('/').pop().split('\\').pop();
    imageUrl = 'https://noxertez.com/mockups/' + archivo;
  }
}

// Detectar marca
const marcas = [];
if (d.marca_noxertez == 1) marcas.push('Noxertez');
if (d.marca_candleholder == 1) marcas.push('Candleholder');
if (d.marca_zen == 1) marcas.push('Zen Garden');
const marca = marcas[0] || 'Noxertez';

// Datos del mockup
const estancia = d.estancia || 'hogar';
const estilo = d.estilo || '';
const decoracion = d.decoracion || '';
const producto = d.nombre_producto || '';

// Hashtags por estancia
const hashtagsEstancia = {
  'salon': '#DecoSalon #LivingRoom #DecoracionSalon',
  'dormitorio': '#DecoDormitorio #Bedroom #DecoHabitacion',
  'cocina': '#DecoKitchen #Cocina #CocinaDecoracion',
  'bano': '#DecoBano #BathroomDecor #Bano',
  'oficina': '#DecoOficina #HomeOffice #OficinaEnCasa',
  'exterior': '#DecoExterior #JardinDeco #TerrazaDeco'
};
const htEstancia = hashtagsEstancia[estancia.toLowerCase()] || '#DecoHogar #HomeDecor';

// Generar caption
const captions = [
  `✨ ${producto ? producto + ' en tu ' + estancia : 'Decoración artesanal para tu ' + estancia} 🏠\n\nCada pieza de ${marca} está hecha a mano con madera natural. Única e irrepetible. 🪵\n\n${htEstancia} #${marca} #MaderaArtesanal #HechoAMano #DecoracionHogar #ArtesaniaEspana`,
  `🪵 Madera natural. Diseño único. Hogar con alma.\n\n${producto ? 'Nuestro ' + producto + ' transforma cualquier ' + estancia + ' en un espacio especial.' : 'Transforma tu ' + estancia + ' con nuestras creaciones artesanales.'}\n\n#${marca} #WoodDecor #MaderaDecoracion ${htEstancia} #HandmadeSpain #ArtesaniaEspañola`,
  `💛 Porque tu hogar merece lo mejor.\n\n${producto || 'Decoración artesanal'} para tu ${estancia} — diseñado y fabricado a mano en España. 🌿\n\n#${marca} #DecoNatural #MaderaViva ${htEstancia} #EcoDecor #SostenibleYBello`
];

// Rotar caption según hora del día
const hora = new Date().getHours();
const idxCaption = hora < 12 ? 0 : hora < 18 ? 1 : 2;
const caption = captions[idxCaption];

return [{ json: {
  mockup_id: d.id,
  image_url: imageUrl,
  caption,
  marca,
  estancia
}}];
